function event_say(e)
	fac = e.other:GetFaction(e.self);

	if(fac < 7) then
		if(e.message:findi("hail")) then
			e.self:Say("Greetings, my friend! You may rest here if you like. There are many dangers in this land. May Tunare watch over you when you depart our camp.");
			eq.signal(70007,5); -- NPC: Ghilanbiddle_Nylwadil
		elseif(e.message:findi("healed")) then
			e.self:Say("I see. Then sit and rest a while. I must conserve my strength for our own interests. When you are ready to leave, go and ask Sigan to [escort you to the pass]. There, you can leave this dangerous land.");
		end
	else
		e.self:Say("You have some nerve to approach a loyal member of the Paladins of Tunare! Run, while you can!");
	end
end

function event_signal(e)
	e.self:Say("Leave our new friend alone, Ghilanbiddle.  He is quite welcome to rest amongst us.");
end

-- EOF Nyrien Lyrdarniel

function event_combat(e)
if e.joined then
eq.set_timer('Hardblur', 180 * 1000);
eq.set_timer('Softblur', 6 * 1000);
else
eq.stop_timer('Hardblur');
eq.stop_timer('Softblur');
end
end

function event_timer(e)
	if (e.timer == 'Hardblur') then
		e.self:WipeHateList();
	elseif (e.timer == 'Softblur') then
		if (math.random(100)<=10) then
			e.self:WipeHateList();
		end
	end
end

-- Source: qeynos/Kasine_Paegra.lua
-- P99: https://wiki.project1999.com/Enchant_Bonethunder
-- items: 13287, 13288, 6358

function event_say(e)
	local standing = e.other.GetModCharacterFactionLevel(e.other, 280);

	if(e.message:findi("hail")) then
		e.self:Say("May the blessings of the Rainkeeper protect you in your travels. I am Kasine Paegra, keeper of the [Order of Thunder] medallions.");
	elseif(e.message:findi("enchant bonethunder")) then
		e.self:Say("I am ordered to only enchant the spell when I have both Bonethunder and 500 gold coins.");
	elseif(standing < 0) then
		e.self:Say("You have proven yourself not only an enemy of the Knights of Thunder, but an enemy of Karana himself.  Now leave, sewer rat!");
	elseif(e.message:findi("order of thunder")) then
		e.self:Say("The Order of Thunder is the medal awarded to a Knight of Thunder who has proven himself superior to the average warrior. All knights and priests of Thunder have one, save for the youngest members. Along with the medal comes great respect. You might say the wearer becomes more charismatic. Should you find one, please return it to Kasine Paegra, unless told otherwise.");
	end
end

function event_trade(e)
	local item_lib = require("items");

	local standing = e.other.GetModCharacterFactionLevel(e.other, 280);

	if(item_lib.check_turn_in(e.trade, {item1 = 6358, gold = 500})) then
		e.self:Say("The Rainkeeper has bestowed this weapon with power once more. Take it and defend our temple.");
		e.other:SummonItem(6358);
	elseif(standing > -1 and item_lib.check_turn_in(e.trade, {item1 = 13287})) then
		e.self:Say("You are a very honorable person. You have returned an Order of Thunder which you truly do not need. I give you the protection of the Rainkeeper to watch over you. May it keep you from harm. Go and serve.");
		e.self:CastSpell(11,e.other:GetID()); -- holy armor
		e.other:Faction(280,10); -- KoT
		e.other:Faction(221,-10); -- BloodSabers
		e.other:Faction(341,7); -- Priest of Life
		e.other:Faction(262,7); -- Guards of Qeynos
		e.other:AddLevelBasedExp(14.2, 3);
	elseif(standing > -1 and item_lib.check_turn_in(e.trade, {item1 = 13288})) then
		e.self:Say("You have returned an Order of Thunder which has been drained of all its power.  I wonder how this could have happened.  No doubt evil is behind this.  Thank you for its return.  I give you the blessings of Karana.  Go and serve the Rainkeeper.");
		e.self:CastSpell(200,e.other:GetID()); -- minor healing
		e.other:Faction(280,20); -- KoT
		e.other:Faction(221,-20); -- BloodSabers
		e.other:Faction(341,15); -- Priest of Life
		e.other:Faction(262,15); -- Guards of Qeynos
		e.other:AddLevelBasedExp(14.2, 3);
	end

	item_lib.return_items(e.self, e.other, e.trade)
end

function event_spawn(e)
	eq.set_timer("first_cast",1000);
	eq.set_timer("cast_spell",10*1000);
end

function event_timer(e)
	if e.timer=="cast_spell" then
		e.self:CastSpell(4795, e.self:GetID()); --Aura of Restoration
	elseif e.timer=="first_cast" then
		e.self:CastSpell(4795, e.self:GetID()); --Aura of Restoration
		eq.stop_timer("first_cast");
	end
end

--Huffin revamp
--Only adds item to loot drop if the event is done properly

function event_spawn(e)
  eq.set_next_hp_event(70);
  e.self:SetOOCRegen(3200);
end

function event_hp(e)
  if(e.hp_event == 70) then
    e.self:Emote("flees to a more secure location in an attempt to defend itself!");
    e.self:SetRunning(true);
    e.self:WipeHateList();
    e.self:SetSpecialAbility(35, 1); --turn on immunity
    e.self:SetSpecialAbility(24, 1); --turn on anti aggro
    eq.set_next_hp_event(30);
    eq.set_timer("activate", 6 * 1000);
    e.self:MoveTo(-1475, 372, -336, 130,true);
  elseif(e.hp_event == 30) then
    e.self:Emote("flees to a more secure location in an attempt to defend itself!");
    e.self:SetRunning(true);
    e.self:WipeHateList();
    e.self:SetSpecialAbility(35, 1); --turn on immunity
    e.self:SetSpecialAbility(24, 1); --turn on anti aggro
    eq.set_timer("activate", 6 * 1000);
    e.self:MoveTo(-437, 279, -337, 130,true);
    e.self:AddItem(60200,1); -- Treanik's Tarnished Axe
  end
end

function event_timer(e)
  eq.stop_timer("activate");
  e.self:SetSpecialAbility(35, 0); --turn off immunity
  e.self:SetSpecialAbility(24, 0); --turn off anti aggro
end

local say_ready = 1;

function event_spawn(e)
	local xloc = e.self:GetX();
	local yloc = e.self:GetY();
	eq.set_proximity(xloc - 30, xloc + 30, yloc - 30, yloc + 30);
end

function event_enter(e)
	e.self:Emote("stammers, his eyes darting about nervously.");
	e.self:Say("Thousands! Why the chamber is literally alive with them. A multitude of skittering insects swarming about on the tiles above.");
end

function event_say(e)
	if say_ready == 1 then
		if e.message:findi("hail") then
			e.self:Emote("exhibits signs of a complete madman. 'This is like a horrible dream. Isolated, trapped, no way out! You, keep back. Stay away from me! Please, someone [awaken me from this nightmare]. AAAAUUUGGH!'");
		elseif e.message:findi("awaken me from this nightmare") then
			e.self:Emote("blinks and a spark of sanity returns. 'Ah, wha... what? How strange. I can see clearly now.'");
			eq.local_emote({e.self:GetX(), e.self:GetY(), e.self:GetZ()}, MT.Yellow, 70, "You feel as if you have made the correct move. However, the exile is already beginning to slip back into insanity. Somehow you must awaken them all, simultaneously.");
			say_ready = 0;
			eq.set_timer("set_ready", 30 * 1000); -- Timer
			eq.signal(296070,296036); -- signal zone_status
		else
			say_ready = 0;
			eq.set_timer("set_ready", 30 * 1000); -- Timer
			exile_fail(e);
		end
	end
end

function event_timer(e)
	if e.timer == "set_ready" then
		eq.stop_timer("set_ready");
		say_ready = 1;
	end
end

function event_signal(e)
	if e.signal == 1 then
		e.self:Say("Thank you for restoring our clarity. Something in this cursed place had stolen away my sanity, and I will not allow it to happen again. Death would be preferable to that endless madness. Be warned, the gateway to the lower reaches of this temple will be unsealed soon. Leave this place before you become mad yourselves!");
	elseif e.signal == 2 then
		exile_fail(e);
	end
end

function exile_fail(e)
	local get_client=eq.get_entity_list():GetRandomClient(e.self:GetX(),e.self:GetY(),e.self:GetZ(),3136);
	--get client within 56 radius
	if get_client.valid then
		e.self:CastSpell(2151,get_client:GetID()); --Contagious Insanity
	end
end

function event_combat(e)
if e.joined then
e.self:Emote("bards and storytellers will sing a song of your death here one day.");
eq.depop_with_timer();
end
end

function event_scale_calc(e)
	local zone_id = eq.get_zone_id();

	if zone_id > 228 and zone_id < 277 then
		e.self:SetScale(1);
	else
		e.self:SetScale(0);
	end
end

function event_combat(e)
  if e.joined then
    e.self:Emote("drips from the stalactite to the stalagmite.");
    eq.depop_with_timer();
  end
end

function event_loot(e)
	if(e.self:Class() == "Warrior" and e.item:GetID() == 60307 ) then
		local qglobals = eq.get_qglobals(e.self);
		if(qglobals["warrior_epic"] ~= nil and qglobals["warrior_epic"] >= "5" and qglobals["warr_epic_bloodfield"] == nil ) then
			eq.spawn2(283157,0,0,e.self:GetX(),e.self:GetY(),e.self:GetZ(),e.self:GetHeading()); -- #a chest (Epic 1.5)
			eq.set_global("warr_epic_bloodfield","1",5,"F");
		end
	end
	if(e.self:Class() == "Monk" and e.item:GetID() == 48137 ) then
		local qglobals = eq.get_qglobals(e.self);
		if(qglobals["monk_epic"] ~= nil and qglobals["monk_epic"] >= "7" and qglobals["monk_epic_bloodfield"] == nil ) then
			eq.spawn2(283157,0,0,e.self:GetX(),e.self:GetY(),e.self:GetZ(),e.self:GetHeading()); -- #a chest (Epic 1.5)
			eq.set_global("monk_epic_bloodfield","1",5,"F");
		end
	end
	if(e.self:Class() == "Monk" and e.item:GetID() == 20435 ) then
		local qglobals = eq.get_qglobals(e.self);
		if(qglobals["monk_epic"] ~= nil and qglobals["monk_epic"] >= "8" and qglobals["monk_epic_keeper"] == nil ) then
			eq.spawn2(283157,0,0,e.self:GetX(),e.self:GetY(),e.self:GetZ(),e.self:GetHeading()); -- #a chest (Epic 1.5)
			eq.set_global("monk_epic_keeper","1",5,"F");
		end
	end
	if(e.self:Class() == "Beastlord" and e.item:GetID() == 57014 ) then
		local qglobals = eq.get_qglobals(e.self);
		if (qglobals["beast_epic"] == "20") then
			if (qglobals["bst_chest_causeway"] == nil) then
				eq.spawn2(893, 0, 0, e.self:GetX(), e.self:GetY(), e.self:GetZ(), e.self:GetHeading()); -- a chest (epic 2.0)
				eq.set_global("bst_chest_causeway", "1", 5, "F");
			end
			return 0;
		else
			return 1;
		end
	end	

end

function event_trade(e)
	local item_lib = require("items");
	item_lib.return_items(e.self, e.other, e.trade);
end

function event_spawn(e)
eq.set_timer("depop", 600 * 1000);
end

