function event_hp(e)
	if (e.hp_event == 90) then
		eq.spawn2(300099, 0, 0, e.self:GetX(), e.self:GetY(), e.self:GetZ(), e.self:GetHeading()):AddToHateList(e.self:GetHateRandom(),1); --loyalist
		eq.set_next_hp_event(75);
