	eq.spawn2(201475, 0,0, 912,-1161, 60, 444); -- NPC: Pain_and_Suffering
	eq.spawn2(201475, 0,0, 824,-1161, 60, 70); -- NPC: Pain_and_Suffering
	eq.spawn2(201475, 0,0, 824,-1078, 60, 180); -- NPC: Pain_and_Suffering
	eq.spawn2(201475, 0,0, 910,-1078, 60, 324); -- NPC: Pain_and_Suffering
end

function despawn_prisoners() 
	local prisoners = { 201476, 201475 }
	for k,v in pairs(prisoners) do
		eq.depop_all(v);
	end
end

function despawn_mobs()
	for k,v in pairs(trial_mobs) do
		eq.depop_all(v);
	end
end

function heal_trial()
	local entity_list = eq.get_entity_list();

	for k,v in pairs(trial_mobs) do
		-- If the NPC is not the Pain and Suffering Mob (no need to heal that one).
		if (v ~= 201475) then 
			local npc = eq.get_entity_list():GetMobByNpcTypeID(v);
			if (npc.valid) then 
				--(772, -1148, 76, 175)
				if ( npc:CalculateDistance(772, -1148, 76) < 175) then
					npc:SetHP(npc:GetMaxHP());
					npc:Emote("shivers as their wounds fade.");
				end
			end
		end
	end
end

